const std = @import("std");

pub fn main() !void {
    const weights = [_]u32{ 2, 3, 4, 5 };
    const values = [_]u32{ 3, 4, 5, 6 };
    const capacity: u32 = 5;
    const n = weights.len;

    var dp: [4 + 1][5 + 1]u32 = [_][5 + 1]u32{[_]u32{0} ** (5 + 1)} ** (4 + 1);

    for (1..n + 1) |i| {
        for (1..capacity + 1) |w| {
            if (weights[i - 1] <= w) {
                dp[i][w] = @max(values[i - 1] + dp[i - 1][w - weights[i - 1]], dp[i - 1][w]);
            } else {
                dp[i][w] = dp[i - 1][w];
            }
        }
    }

    std.debug.print("Max value: {}\n", .{dp[n][capacity]});
}

